  p_bmLines = L1_bmLines;
  p_bmStreak = L1_bmStreak;
  p_bmLong = L1_bmLong;
  p_bmRough = L1_bmRough;
  p_bmMetal = L1_bmMetal;
  p_bmRelief = L1_bmRelief;
  p_bmMirror = L1_bmMirror;
  p_bmSky = L1_bmSky;
  p_bmWall = L1_bmWall;
  p_bmFloor = L1_bmFloor;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 bmG = dot(s3, s3) > 0.25 ? normalize(s3) : vec2(1.0, 0.0);
    // along the brushing, across it
    vec2 bmQ = vec2(dot(uv, bmG), dot(uv, vec2(-bmG.y, bmG.x)));
    // the scratches: noise stretched far along the brushing, one row a scratch, faded to its mean where a scratch is
    // under a pixel; a few deeper, longer ones over them
    float bmFine = mix(0.5, kn(vec2(bmQ.x * p_bmLong * 4.0, bmQ.y * p_bmLines) + seed), kfade(2.0 / p_bmLines));
    float bmDeep = mix(0.5, kn(vec2(bmQ.x * p_bmLong, bmQ.y * p_bmLines * 0.18) + seed + 17.0), kfade(8.0 / p_bmLines));
    float bmS = 0.75 * bmFine + 0.25 * smoothstep(0.35, 0.8, bmDeep);
    // a slow cloud of the belt's passes, so a big sheet isn't one flat grey
    float bmPass = kfbm4(vec2(bmQ.x * 0.6, bmQ.y * 7.0) + seed * 1.3);
    vec3 bmC = p_bmColour * (1.0 + p_bmStreak * (bmS - 0.5) * 0.9) * (0.94 + 0.12 * bmPass);
    k.colour = bmC;
    k.metal = p_bmMetal;
    k.rough = clamp(p_bmRough + 0.12 * (bmS - 0.5) + 0.05 * (bmPass - 0.5), 0.03, 1.0);
    k.height = p_bmRelief * (bmS - 0.5);
    // the room mirrored, smeared along the brushing: its ray tipped across the scratches by each one's slope
    vec3 bmV = normalize(wp - cameraPosition);
    vec3 bmN = normalize(wn);
    vec3 bmR = reflect(bmV, bmN);
    float bmCos = clamp(dot(-bmV, bmN), 0.0, 1.0);
    float bmFres = 0.7 + 0.3 * pow(1.0 - bmCos, 3.0);
    vec3 bmRoom = rmRoom(normalize(bmR + 0.08 * (bmS - 0.5) * vec3(1.0, 0.0, 1.0)), clamp(p_bmRough * 2.2, 0.0, 1.0), p_bmSky, p_bmWall, p_bmFloor);
    k.glow = p_bmMirror * bmRoom * bmC * bmFres * (0.85 + 0.3 * bmS);
    if (lookView > 0.5 && lookView < 1.5) k.colour = vec3(0.5 + 0.5 * bmG.x, 0.5 + 0.5 * bmG.y, 0.5);

}

void look_2(inout Look k) {
  p_pmColour = L2_pmColour;
  p_pmPeel = L2_pmPeel;
  p_pmRelief = L2_pmRelief;
  p_pmRough = L2_pmRough;
  p_pmCoat = L2_pmCoat;
  p_pmCoatRough = L2_pmCoatRough;
  p_pmOil = L2_pmOil;
  p_pmOilColour = L2_pmOilColour;
  p_pmOilStreaks = L2_pmOilStreaks;
  p_pmOilRough = L2_pmOilRough;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float pmF = kfade(2.0 / p_pmPeel);
    float pmPeel = (1.0 - kcell(uv * p_pmPeel + seed)) * pmF;
    float pmFine = kn(uv * p_pmPeel * 2.7 + seed + 3.0) * kfade(1.0 / p_pmPeel);
    k.colour = p_pmColour * (0.985 + 0.03 * kfbm4(uv * 2.0 + seed));
    k.rough = clamp(p_pmRough + 0.04 * pmFine, 0.0, 1.0);
    k.height = p_pmRelief * (0.75 * pmPeel + 0.25 * pmFine);
    k.clearcoat = p_pmCoat;
    k.clearcoatRough = p_pmCoatRough;
    if (p_pmOil > 0.0) {
      // runs: noise drawn out along u, fine across v; blotches: a slow fbm; thick where both lie
      float pmRun = kn(vec2(uv.x * p_pmOilStreaks * 0.12, uv.y * p_pmOilStreaks) + seed + 5.0);
      float pmBlot = kfbm(uv * 2.5 + seed + 9.0);
      float pmThick = smoothstep(0.4, 0.8, 0.55 * pmRun + 0.45 * pmBlot);
      float pmO = clamp(p_pmOil * (0.15 + 0.85 * pmThick), 0.0, 1.0);
      vec3 pmOilC = p_pmOilColour * (0.7 + 0.6 * kn(vec2(uv.x * 3.0, uv.y * 40.0) + seed));
      k.colour = mix(k.colour, pmOilC, pmO);
      k.rough = mix(k.rough, p_pmOilRough + 0.5 * (1.0 - pmThick), pmO);
      k.clearcoat = mix(k.clearcoat, 0.0, pmO);
      k.height += p_pmOil * 0.00006 * pmThick;
    }

}

void look_3(inout Look k) {
  p_cmColour = L3_cmColour;
  p_cmSand = L3_cmSand;
  p_cmRelief = L3_cmRelief;
  p_cmPits = L3_cmPits;
  p_cmRough = L3_cmRough;
  p_cmMetal = L3_cmMetal;
  p_cmBloom = L3_cmBloom;
  p_cmBloomColour = L3_cmBloomColour;
  p_cmHeat = L3_cmHeat;
  p_cmHeatColour = L3_cmHeatColour;
  p_cmGrime = L3_cmGrime;
  p_cmGrimeColour = L3_cmGrimeColour;
  p_cmMirror = L3_cmMirror;
  p_cmSky = L3_cmSky;
  p_cmWall = L3_cmWall;
  p_cmFloor = L3_cmFloor;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the sand's grain: fine bumps, and here and there a pit, each fading to its mean where finer than a pixel
    float cmF = kfade(2.0 / p_cmSand);
    float cmG = mix(0.5, kn(uv * p_cmSand + seed), cmF);
    float cmG2 = mix(0.5, kn(uv * p_cmSand * 0.43 + seed + 5.0), kfade(4.0 / p_cmSand));
    float cmP = p_cmPits * (1.0 - smoothstep(0.0, 0.22, kcell(uv * p_cmSand * 0.3 + seed + 3.0))) * kfade(8.0 / p_cmSand);
    // the faces that look down (wn.y below 0) carry the oil and road grime, the rest a little of it in patches
    float cmDown = smoothstep(0.15, -0.85, wn.y);
    float cmGr = clamp(p_cmGrime * (0.2 + 0.9 * cmDown) * smoothstep(0.3, 0.75, kfbm(uv * 4.5 + seed + 7.0) + 0.3 * cmDown), 0.0, 1.0);
    float cmB = p_cmBloom * smoothstep(0.45, 0.85, kfbm4(uv * 3.0 + seed + 1.0));
    float cmH = p_cmHeat * smoothstep(0.25, 0.75, kfbm4(uv * 2.2 + seed + 13.0));
    float cmS = 0.6 * cmG + 0.4 * cmG2;
    vec3 cmC = p_cmColour * (0.9 + 0.2 * cmS) * (1.0 - 0.45 * cmP);
    cmC = mix(cmC, p_cmBloomColour, cmB);
    cmC = mix(cmC, p_cmHeatColour * (0.85 + 0.3 * cmS), cmH);
    cmC = mix(cmC, p_cmGrimeColour, clamp(cmGr + 0.6 * cmP * p_cmGrime, 0.0, 1.0));
    k.colour = cmC;
    k.metal = p_cmMetal * (1.0 - 0.5 * cmB) * (1.0 - 0.8 * cmGr);
    k.rough = clamp(p_cmRough + 0.12 * (cmS - 0.5) + 0.2 * cmB + 0.25 * cmGr + 0.2 * cmP, 0.05, 1.0);
    k.height = p_cmRelief * (cmS - 0.5 - 0.9 * cmP) + 0.00003 * cmGr;
    k.ao = 1.0 - 0.35 * cmP;
    // the room mirrored softly, as a satin casting shows it, less where it is bloomed or grimed
    vec3 cmV = normalize(wp - cameraPosition);
    vec3 cmN = normalize(wn);
    float cmCos = clamp(dot(-cmV, cmN), 0.0, 1.0);
    vec3 cmRoom = rmRoom(reflect(cmV, cmN), clamp(p_cmRough * 1.8, 0.0, 1.0), p_cmSky, p_cmWall, p_cmFloor);
    k.glow = p_cmMirror * cmRoom * cmC * (0.7 + 0.3 * pow(1.0 - cmCos, 3.0)) * (1.0 - cmGr) * (1.0 - 0.5 * cmB);

}

void look_4(inout Look k) {
  p_pcTint = L4_pcTint;
  p_pcSky = L4_pcSky;
  p_pcHorizon = L4_pcHorizon;
  p_pcFloor = L4_pcFloor;
  p_pcBlur = L4_pcBlur;
  p_pcWindow = L4_pcWindow;
  p_pcRough = L4_pcRough;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec3 pcN = normalize(wn);
    vec3 pcI = normalize(wp - cameraPosition);
    vec3 pcR = reflect(pcI, pcN);
    // how far up the reflected line points: -1 straight down, 1 straight up
    float pcUp = pcR.y;
    float pcB = p_pcBlur;
    // the floor below, the sky above, a bright band at the horizon between them
    vec3 pcEnv = mix(p_pcFloor, p_pcSky, smoothstep(-pcB, pcB, pcUp));
    pcEnv = mix(pcEnv, p_pcHorizon, exp(-pcUp * pcUp / max(0.002, pcB * pcB * 0.25)) * 0.55);
    // a soft window of light high up and toward one side, so a round part has its one bright spot
    float pcW = smoothstep(0.82, 0.97, dot(pcR, normalize(vec3(0.35, 0.85, 0.4))));
    pcEnv += vec3(p_pcWindow) * pcW;
    // the faint swirls of polishing, gone to their mean where a pixel is as wide
    float pcSw = mix(0.5, kn(uv * 900.0 + seed), kfade(0.002));
    k.colour = clamp(pcEnv * p_pcTint * (0.98 + 0.04 * pcSw), 0.0, 1.0);
    k.metal = 0.0;
    k.rough = p_pcRough;

}

void look_5(inout Look k) {
  p_rbColour = L5_rbColour;
  p_rbBloom = L5_rbBloom;
  p_rbBloomAmount = L5_rbBloomAmount;
  p_rbGrit = L5_rbGrit;
  p_rbRelief = L5_rbRelief;
  p_rbRough = L5_rbRough;
  p_rbSheen = L5_rbSheen;
  p_rbSheenRough = L5_rbSheenRough;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float rbG = kn(uv * p_rbGrit + seed) * kfade(2.0 / p_rbGrit);
    float rbP = 1.0 - smoothstep(0.0, 0.25, kcell(uv * p_rbGrit * 0.25 + seed)) ;
    rbP *= kfade(6.0 / p_rbGrit);
    float rbB = smoothstep(0.35, 0.8, kfbm4(uv * 4.0 + seed)) * p_rbBloomAmount;
    k.colour = mix(p_rbColour, p_rbBloom, rbB) * (0.95 + 0.1 * rbG) * (1.0 - 0.3 * rbP);
    k.rough = clamp(p_rbRough + 0.08 * rbB + 0.05 * rbG, 0.0, 1.0);
    k.height = p_rbRelief * (rbG - 0.6 * rbP);
    k.sheen = p_rbSheen;
    k.sheenRough = p_rbSheenRough;

}







Look lookRun(int id) {
  Look k = lookStart();
  switch (id) {
    case 0: look_0(k); break;
    case 1: look_1(k); break;
    case 2: look_2(k); break;
    case 3: look_3(k); break;
    case 4: look_4(k); break;
    case 5: look_5(k); break;
  }
  if (lookDebug > 0.5) {
    switch (id) {
      case 0: k.colour = vec3(0.01599629336550963, 0.01520851442291271, 0.014443843596092545); break;
      case 1: k.colour = vec3(0.6724431569576875, 0.6866853124353135, 0.7011018919329731); break;
      case 2: k.colour = vec3(0.006995410187265387, 0.006995410187265387, 0.008023192985384994); break;
      case 3: k.colour = vec3(0.32314320911295075, 0.3277780980565422, 0.33245153634617935); break;
      case 4: k.colour = vec3(0.6866853124353135, 0.7011018919329731, 0.7304607400903537); break;
      case 5: k.colour = vec3(0.006995410187265387, 0.006995410187265387, 0.006995410187265387); break;
    }
  }
  return k;
}
